static void orbit_print_kynx_gradient(const char* text) {
    size_t len = strlen(text);
    if (len == 0) return;
    for (size_t i = 0; i < len; i++) {
        float t = (float)i / (float)(len > 1 ? len - 1 : 1);
        int r = (int)(96.0f + t * (30.0f - 96.0f));
        int g = (int)(165.0f + t * (58.0f - 165.0f));
        int b = (int)(250.0f + t * (138.0f - 250.0f));
        printf("\x1b[38;2;%d;%d;%dm%c", r, g, b, text[i]);
    }
    printf("\x1b[0m");
}

static int orbit_color_enabled(void) {
    const char* no_color = getenv("NO_COLOR");
    if (no_color != NULL && no_color[0] != 0) return 0;
    const char* term = getenv("TERM");
    if (term != NULL && strcmp(term, "dumb") == 0) return 0;
    return 1;
}

static void orbit_render_server_banner(int port, int num_workers, int kynx_enabled, double ready_ms) {
    if (orbit_color_enabled() == 0) {
        printf("\n  Orbit 0.1.0\n\n");
        printf("   - Local: http://localhost:%d\n", port);
        printf("   - Workers: %d\n", num_workers);
        if (kynx_enabled) {
            printf("   - Secured by Kynx.\n");
        }
        printf("\n- Starting...\n");
        printf("- Ready in %.1f ms\n\n", ready_ms);
        fflush(stdout);
        return;
    }
    printf("\n  Orbit 0.1.0");
    printf("\n\n");

    printf("   \x1b[90m-\x1b[0m \x1b[37mLocal:\x1b[0m \x1b[1;37mhttp://localhost:%d\x1b[0m\n", port);
    printf("   \x1b[90m-\x1b[0m \x1b[37mWorkers:\x1b[0m \x1b[1;37m%d\x1b[0m\n", num_workers);

    if (kynx_enabled) {
        printf("   \x1b[90m-\x1b[0m ");
        orbit_print_kynx_gradient("Secured by Kynx.");
        printf("\n");
    }

    printf("\n\x1b[32m✓\x1b[0m \x1b[37mStarting...\x1b[0m\n");
    printf("\x1b[32m✓\x1b[0m \x1b[37mReady in %.1f ms\x1b[0m\n\n", ready_ms);
    fflush(stdout);
}

